-- public.set_entry_feedback
-- Generated by scripts/schema-snapshot.mjs from project heuhqqoxyggawuckxocp. Do not edit by hand.

-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.set_entry_feedback(p_submission uuid, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin   uuid := auth.uid();
  v_creator uuid;
  v_conv    uuid;
  v_title   text;
  v_body    text := btrim(p_body);
begin
  if not is_admin() then
    raise exception 'Only the team can leave feedback on an entry';
  end if;
  if v_body = '' then
    raise exception 'Feedback cannot be empty';
  end if;

  select s.creator_id, c.title
    into v_creator, v_title
  from submissions s
  join challenges c on c.id = s.challenge_id
  where s.id = p_submission;

  if v_creator is null then
    raise exception 'That entry does not exist';
  end if;

  insert into submission_feedback (submission_id, body, author_id)
  values (p_submission, v_body, v_admin)
  on conflict (submission_id) do update
    set body = excluded.body, author_id = excluded.author_id, updated_at = now();

  -- Never DM yourself. An admin reviewing their own entry still gets the
  -- feedback saved; there is just nobody to send it to.
  if v_creator = v_admin then
    return;
  end if;

  select id into v_conv from conversations
  where kind = 'direct'
    and ((participant_a = v_admin and participant_b = v_creator)
      or (participant_a = v_creator and participant_b = v_admin))
  limit 1;

  if v_conv is null then
    insert into conversations (participant_a, participant_b)
    values (v_admin, v_creator)
    returning id into v_conv;
  end if;

  insert into direct_messages (conversation_id, sender_id, recipient_id, body, submission_id)
  values (
    v_conv, v_admin, v_creator,
    'Feedback on your entry for ' || coalesce(v_title, 'the challenge') || E'\n\n' || v_body,
    p_submission
  );
end;
$function$;
